window.DOSIK=window.DOSIK||{};DOSIK["yc_research1"]={"1":[{"t":"tree","title":"상담연구의 요건","root":"상담연구","branches":[["자료 수집","연구자료는 합리적이고 체계적인 방법으로 수집해야 한다"],["결론","연구자는 객관적이고 타당한 근거를 통해 결론을 도출해야 한다"],["이론 수정","한 번 정립된 이론도 수정될 수 있어야 한다 · 선행 연구의 상담 이론은 수정될 수 있다"],["재검증","기존의 연구 결과도 반복해서 검증할 수 있어야 한다"],["현장 활용","상담효과의 객관적인 연구결과를 현장에 적극 활용한다"]]},{"t":"vs","title":"양적연구와 구성주의","cols":[{"name":"양적연구","items":["연구조건과 과정이 같으면 연구자에 관계없이 동일한 결론에 도달해야 한다"]},{"name":"구성주의","items":["사례연구, 해석, 재구성 등에 초점을 둔다"]}]}],"2":[{"t":"tree","title":"연구가설","root":"연구가설","branches":[["서술","변수 간에 기대되는 관계를 검증 가능한 형태로 서술한다"],["검증","이론적 분포를 바탕으로 통계적 가설을 검증한다"],["진술","하나의 가설은 하나의 관계만을 검증하도록 진술하는 것이 바람직하다"]]},{"t":"vs","title":"등가설과 부등가설","cols":[{"name":"등가설","items":["등호를 포함한 형태로 기술한다"]},{"name":"부등가설","items":["부등호를 포함한 형태로 기술한다"]}]}],"3":[{"t":"vs","title":"조절변수와 매개변수","cols":[{"name":"조절변수","items":["독립변수와 종속변수 간 관계의 강도에 영향을 준다"]},{"name":"매개변수","items":["독립변수의 영향을 종속변수로 전달한다"]}]},{"t":"cause","title":"인과관계의 필요조건","causes":["독립변수와 종속변수 간의 비허위적 관계","독립변수와 종속변수 간의 시간적 선후관계"],"result":"두 변수 간 인과관계 성립의 필요조건이다"},{"t":"def","term":"종속변수가 상수","text":"독립변수와의 인과관계는 불가능하다"}],"4":[{"t":"table","title":"표본추출 방법","head":["방법","내용"],"rows":[["우연표본추출(accidental sampling)","연구자가 편의성을 고려하여 임의로 표본을 추출하는 방식이다"],["단순무작위표본추출(simple random sampling)","모집단의 요소가 표집될 확률은 같다"],["체계적표본추출(systematic sampling)","전체 목록에서 매 k번째 요소를 추출한다"],["층화표본추출(stratified sampling)","모집단을 층(strata)으로 구분한 후, 각 층에서 무작위 표본추출하는 방법이다"],["확률표본추출","모집단의 표집단위가 표본에 선정될 수 있는 확률을 사전에 알 수 있다"],["집락화되어 있을 경우","모집단의 구성요소들이 집락화되어 있을 경우 유용하다"]]}],"5":[{"t":"table","title":"척도의 수준","head":["척도","특징"],"rows":[["명목척도","연구대상을 상호배타적으로 분류한다"],["등간척도","점수들의 순위에 대한 정보를 포함하고 있다 · 점수들의 차이와 서열관계를 측정할 수 있다, 표준편차와 상관계수를 구할 수 있다 · 평정자가 진술문 간의 등간성을 판단할 수 있다는 것을 전제로 한다"],["비율척도","0은 측정하고자 하는 특성의 정도가 전혀 없음을 의미한다 · 측정 점수를 바탕으로 몇 배 더 크다는 표현이 가능하다"]]}],"6":[{"t":"table","title":"신뢰도 추정","head":["방법","내용","단점"],"rows":[["검사-재검사법","측정을 반복 실시하여 측정도구의 안정성을 평가한다","응답자가 첫 번째 응답을 기억하여 두 번째 응답을 할 수 있다"],["동형검사법","동일한 개념을 복수의 다른 측정도구를 이용하여 평가한다","첫 번째 측정도구와 매우 유사한 동형의 다른 측정도구를 개발하기 어렵다"]]},{"t":"tree","title":"신뢰도를 높이는 방법","root":"신뢰도","branches":[["문항","동일현상을 측정하는 항목의 문항을 늘린다"],["표현","문항의 모호한 표현을 제거한다"],["질문","중요한 질문의 경우 유사한 질문을 2회 이상 제시한다"],["지침서","측정에 대한 세부지침서를 조사 대상자에게 제공한다"]]},{"t":"cause","title":"검사 난이도","causes":["능력을 측정하는 검사의 난이도가 너무 높거나 너무 낮음"],"result":"검사의 신뢰도가 저하된다"}],"7":[{"t":"tree","title":"타당도","root":"타당도","branches":[["정의","측정 도구가 측정하고자 하는 특성을 얼마나 정확하게 측정하고 있는가를 의미한다"],["준거관련(criterion-related)타당도","공존(concurrent)타당도와 예측(predictive)타당도가 해당한다"],["구인(construct)타당도","수렴(convergent)타당도와 판별(discriminant)타당도가 해당한다 · 요인분석 기법을 이용하여 확인할 수 있다"]]}],"9":[{"t":"tree","title":"무선배치와 교차설계","root":"무선 할당","branches":[["무선배치","가외변인 효과의 통제를 위해 활용된다"],["교차설계","적용한 연구에서 처치 순서를 무선으로 할당하면 연구의 타당도를 높일 수 있다"]]},{"t":"vs","title":"간편한 설계의 장점과 한계","cols":[{"name":"장점","items":["간편하고 시간과 비용이 절감되어 사회과학 조사에서 활용되고 있다"]},{"name":"한계","items":["다양한 외생변수가 개입될 여지가 있다","두 집단 자체의 차이가 통제되지 않는다","집단 구성에 있어 연구자의 선택적 편의가 발생할 수 있다"]}]},{"t":"tree","title":"통합 설계","root":"통제집단 사전 - 사후측정설계와 통제집단 사후측정설계를 통합한 형태","branches":[["복잡성","설계의 복잡성으로 인해 시간과 비용의 문제가 발생한다"],["두 번째 실험집단","사전검사 여부를 제외하면 첫 번째 실험집단과 동일한 조건이다"],["효과","실험처치와 사전검사 간의 상호작용 통제에 효과적이다"]]},{"t":"def","term":"통제집단 사후측정설계","text":"독립변수의 효과는 O1과 O2의 차이이다"}],"10":[{"t":"tree","title":"단일사례연구설계","root":"단일사례연구설계","branches":[["측정","한 사람 또는 한 개 집단의 행동 또는 구성개념을 체계적이고 반복적으로 측정한다"],["비교대상","처치 효과를 평가할 때 다른 사람이 아니라 참여자 자신이 비교대상이 된다"],["자료","양적 자료뿐 아니라 질적 자료를 수집하여 참여자의 생생한 경험을 보고할 수 있다"],["ABAB 설계","이월효과(carryover effect)가 존재할 가능성이 있다"]]}],"11":[{"t":"tree","title":"조사연구","root":"조사연구","branches":[["파악","특정 집단 내 문제의 패턴, 원인 등을 파악할 수 있다"],["자료 수집","대면, 우편, 전화, 온라인 웹사이트를 통해 자료를 수집한다"],["표본","모집단을 대표할 수 있는 표본으로부터 자료를 수집하는 것이 중요하다"],["문항 수정","연구 대상자의 문화적 배경에 따라 문항이나 질문 방식을 수정할 수 있다"]]}],"14":[{"t":"tree","title":"상관계수","root":"상관계수","branches":[["피어슨 상관계수","절대값의 크기는 두 변수 간 · 선형적 관계의 강도를 나타낸다"],["범위","-1에서 +1의 값을 가진다"],["강한 상관관계","절댓값이 0.8 이상이다"],["음의 상관관계","산포도에서 한 변수의 값이 증가함에 따라 · 다른 변수의 값이 감소할 경우이다"]]}],"15":[{"t":"tree","title":"공분산분석","root":"공분산분석","branches":[["분석","공변량(covariate)이 종속변수에 미치는 영향을 통계적으로 통제한 후 독립변수가 종속변수에 미치는 영향을 분석한다"],["자료 수집","공변량(covariate)에 대한 자료는 실험 전에 수집하는 것을 전제한다"],["모형","회귀분석과 분산분석이 혼합된 모형으로 볼 수 있다"],["가정","집단 내에서의 종속변수에 대한 공변량의 회귀계수가 집단 간에 동일하다는 가정을 충족해야 한다"]]}],"16":[{"t":"tree","title":"요인분석","root":"요인분석","branches":[["요인적재량","각 변수와 요인 사이의 상관관계 정도를 의미한다"],["예비단계","회귀분석이나 판별분석의 예비단계로 활용할 수 있다"],["사각회전","요인들 간의 관계가 완전히 독립적이지 못한 경우에는 사각회전(oblique rotation) 방식이 적절하다"],["고유치(eigenvalue)","각 요인별로 모든 변수의 요인적재량을 제곱하여 더한 값이다"]]}],"18":[{"t":"tree","title":"질적연구의 특징","root":"질적연구","branches":[["가치","연구과정에서 연구자의 가치가 개입된다"],["자료 수집","연구자료는 연구자의 참여나 관찰을 통해 수집된다"],["절차 변경","연구 수행 시 연구 절차의 변경 가능성을 사전에 고려해야 한다"],["목적","현상에 대한 심층적 이해를 목적으로 한다"],["맥락","자연스러운 맥락에서 인간 행동을 탐구한다"]]},{"t":"tree","title":"코딩을 쓰는 연구","root":"개방코딩, 축코딩, 선택코딩","branches":[["자료분석","개방코딩, 축코딩, 선택코딩으로 진행된다"],["개발","코빈과 스트라우스(J. Corbin & A. Strauss)에 의해 개발되었다"],["강조","체계적인 자료분석을 통해 이론을 생성하는 것을 강조한다"],["철학적 기반","상징적 상호작용론에 철학적 기반을 두고 있다"]]},{"t":"flow","title":"자료분석 과정","steps":["개방코딩","축코딩","선택코딩"]}],"20":[{"t":"table","title":"논문의 구성","head":["항목","내용"],"rows":[["초록","연구의 주요 내용을 간결하게 서술한다"],["서론","연구자의 문제의식과 연구의 필요성을 서술한다"],["연구방법","연구의 대상, 절차 및 자료수집 방법에 대해 서술한다"],["논의 및 결론","연구 결과가 실무 및 관련 이론에 갖는 시사점을 서술한다"]]},{"t":"tree","title":"연구참여자에게 고지","root":"연구참여자에게 고지","branches":[["이득과 위험","연구자는 자료수집 전에 연구참여의 이득과 위험을 고지한다"],["연구 절차","연구목적, 연구과정, 참가자가 따라야 할 연구절차를 고지한다"],["비밀 보장","연구참여자의 자료는 무기명으로 처리되어 비밀이 보장된다는 것을 고지한다"]]},{"t":"table","title":"연구윤리","head":["유형","내용"],"rows":[["위조","연구 과정에서 나타나지 않은 데이터를 실재하는 것처럼 제시하는 경우"],["변조","연구자료를 의도적으로 실제와 다르게 변경하는 경우"],["부당한 저자 표기","저자로서 정당한 자격을 갖춘 사람에게 저자 자격을 부여하지 않는 경우"],["출처 표시","연구자 자신의 이전 저작물을 인용할 때도 출처 표시를 준수해야 한다"]]},{"t":"def","term":"연구자의 의무","text":"선입견, 예측, 사적인 욕구에 이끌리지 않고 결과를 정직하게 보고하는 것"}]};
